// eslint-disable-next-line import/no-nodejs-modules
import {Buffer} from 'buffer'

/**
 * Capitalizes the first Unicode codepoint of a string and lowercases the rest.
 */
export function capitalize(s: string): string {
  const first = [...s][0]
  if (!first) return s
  return first.toUpperCase() + s.slice(first.length).toLowerCase()
}

export async function encryptString(itemValue: string, publicKey: string) {
  const {encrypt} = await import('@github-ui/encryption')
  return Buffer.from(await encrypt(publicKey, itemValue)).toString('base64')
}
